<script module lang="ts">
/**
 * A Dialog preset for confirming an action (`design/components/confirm-dialog.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/confirm-dialog.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, setContext, type Snippet } from 'svelte'

import { agentMember, joinSlot, watchEffect } from '@polymorph/svelte'
import Button from '../controls/Button.svelte'
import Dialog from './Dialog.svelte'
import FormField from '../controls/FormField.svelte'
import Input from '../controls/Input.svelte'

export type ConfirmTone = NonNullable<ConfirmDialogProps['tone']>

export interface ConfirmDialogProps {
  cancelLabel?: string
  closeLabel?: string
  /**
   * The action's verb; it has no default, so the caller must name the action.
   */
  confirmLabel: string
  /**
   * A typed confirmation: the phrase the person types before the confirm enables, such as the
   * name of the project being deleted. The body draws its field, and focus starts there in both
   * tones.
   */
  confirmWith?: string
  /**
   * The phrase field's error while its text cannot become the phrase, `The text does not match`
   * by default.
   */
  confirmWithError?: string
  /**
   * The phrase field's label, `Type {confirmWith} to confirm` by default. Localized hosts pass
   * their own, with the phrase in it.
   */
  confirmWithLabel?: string
  /**
   * Required, because a confirm must say what is at stake.
   */
  description: string
  /**
   * A Promise puts the dialog into its pending state until it settles.
   */
  onConfirm?: () => void | Promise<void>
  onOpenChange?: (open: boolean) => void
  open?: boolean
  /**
   * Dialog's `presentation`, passed through (the sheet presentation,
   * `design/components/README.md`). A confirm is the content-light dialog this option is for.
   * `'sheet'` keeps the sm card above `30rem` and uses a bottom sheet below it. Footer order,
   * cancel-first initial focus and the pending lock are the same in both forms.
   */
  presentation?: 'auto' | 'sheet'
  title: string
  /**
   * `accent` for consequential but safe actions; the `danger` default is for destructive ones.
   */
  tone?: 'accent' | 'danger'
  trigger?: Snippet
}
</script>

<script lang="ts">
let {
  cancelLabel = 'Cancel',
  closeLabel = 'Close',
  confirmLabel,
  confirmWith,
  confirmWithError = 'The text does not match',
  confirmWithLabel,
  description,
  onConfirm,
  onOpenChange,
  open,
  presentation = 'auto',
  title,
  tone = 'danger',
  trigger,
}: ConfirmDialogProps = $props()
const joined = joinSlot(undefined, () => ({}))
setContext('polymorph:identity', 'confirm-dialog')
const borrowed: { element?: () => Element | null | undefined } = {}
setContext('polymorph:borrowed', borrowed)
let mirror = $state(false)
let pending = $state(false)
let typed = $state('')
const current = $derived(open ?? mirror)
const phrase = $derived(confirmWith === undefined ? undefined : confirmWith.trim().toLowerCase())
const entered = $derived(typed.trim().toLowerCase())
const holds = $derived(phrase === undefined || entered === phrase)
const wrong = $derived(phrase !== undefined && entered !== '' && !phrase.startsWith(entered))
const setOpen = $derived((next: boolean) => {
  mirror = next
  onOpenChange?.(next)
})
const confirm = $derived(async () => {
  const result = onConfirm?.()
  if (!(result instanceof Promise)) {
    setOpen(false)
    return
  }
  pending = true
  try {
    await result
    setOpen(false)
  } finally {
    pending = false
  }
})
const effect1 = () => {
  current && (typed = '')
}
watchEffect(effect1, { watch: () => current, mount: false })
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'ConfirmDialog',
    element: () => borrowed.element?.(),
    state: () => ({ open: current, pending: pending }),
    actions: {
      cancel: () =>
        (() => {
          if (pending) throw new Error('The confirmed action is running; it cannot be cancelled.')
          setOpen(false)
        })(),
    },
    withholds: () => borrowed.element?.(),
  })
  release2 = () => {
    ran()
  }
}
watchEffect(effect2)
onDestroy(() => release2?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#snippet triggerOfDialog1()}{@render trigger?.()}{/snippet
  }{#snippet childrenOfDialog2()
    }<FormField
      label={confirmWithLabel ?? `Type ${confirmWith} to confirm`}
      error={wrong ? confirmWithError : undefined}
      ><Input
        value={typed}
        autoComplete="off"
        exact={true}
        disabled={pending}
        onChange={(event) => { typed = event }}
    /></FormField
  >{/snippet
  }{#snippet footerOfDialog3()
    }<Button
      variant="outline"
      tone="neutral"
      label={cancelLabel}
      disabled={pending}
      onClick={() => { setOpen(false) }}
    /><Button
      variant="solid"
      {tone}
      label={confirmLabel}
      loading={pending}
      disabled={!holds}
      onClick={() => { confirm() }}
  />{/snippet
  }<Dialog
    {closeLabel}
    size="sm"
    {title}
    {description}
    open={current}
    {presentation}
    dismissible={!pending}
    alert={tone === 'danger'}
    initialFocus={tone === 'danger' && confirmWith === undefined ? 'dismiss' : 'primary'}
    onOpenChange={(event) => { setOpen(event) }}
    trigger={triggerOfDialog1}
    children={confirmWith !== undefined ? childrenOfDialog2 : undefined}
    footer={footerOfDialog3}
/>{/if
}{@render joined.end?.()}
